UPDATE feedback_items SET heading = 'Simple Present', body = 'When to use: For facts, habits, routines and situations that are generally true, including the findings of a study.
Look for: *always*, *usually*, *often*, *rarely*, *every day*, and verbs such as *know*, *believe*, *seem* and *contain*.
Example: The study *shows* that regular study habits lead to higher scores.
Watch out: Verbs that describe states, thoughts or feelings (*know*, *believe*, *own*, *contain*) are not normally used with *-ing*: *I believe…*, not *I am believing…*.', fields_json = '[{"label":"When to use","text":"For facts, habits, routines and situations that are generally true, including the findings of a study."},{"label":"Look for","text":"*always*, *usually*, *often*, *rarely*, *every day*, and verbs such as *know*, *believe*, *seem* and *contain*."},{"label":"Example","text":"The study *shows* that regular study habits lead to higher scores."},{"label":"Watch out","text":"Verbs that describe states, thoughts or feelings (*know*, *believe*, *own*, *contain*) are not normally used with *-ing*: *I believe…*, not *I am believing…*."}]' WHERE feedback_code = '01-01-01-003-01-00';
UPDATE feedback_items SET heading = 'Present Perfect Continuous (*has/have been* + *-ing*)', body = 'When to use: To focus on how long an activity has been going on from the past until now, or on an activity that has just stopped and still has visible results.
Look for: *for six hours*, *all morning*, *since 8 a.m.*, *lately*, *recently*.
Example: The board *has been reviewing* the reports all morning.
Watch out: When the focus is on a result or on how many things are finished, use *has/have* + past participle: *She has written three reports*, not *She has been writing three reports*.', fields_json = '[{"label":"When to use","text":"To focus on how long an activity has been going on from the past until now, or on an activity that has just stopped and still has visible results."},{"label":"Look for","text":"*for six hours*, *all morning*, *since 8 a.m.*, *lately*, *recently*."},{"label":"Example","text":"The board *has been reviewing* the reports all morning."},{"label":"Watch out","text":"When the focus is on a result or on how many things are finished, use *has/have* + past participle: *She has written three reports*, not *She has been writing three reports*."}]' WHERE feedback_code = '01-01-01-003-02-00';
