UPDATE feedback_items SET heading = 'Simple Past', body = 'When to use: For actions and situations that were completed at a specific time in the past.
Look for: *yesterday*, *last week*, *in 2022*, *three days ago*, *when I was a child*.
Example: The YouTubers *had* a meeting yesterday afternoon.
Watch out: If the sentence gives a finished past time, do not use *has/have* + past participle: *I submitted the form last Tuesday*, not *I have submitted the form last Tuesday*.', fields_json = '[{"label":"When to use","text":"For actions and situations that were completed at a specific time in the past."},{"label":"Look for","text":"*yesterday*, *last week*, *in 2022*, *three days ago*, *when I was a child*."},{"label":"Example","text":"The YouTubers *had* a meeting yesterday afternoon."},{"label":"Watch out","text":"If the sentence gives a finished past time, do not use *has/have* + past participle: *I submitted the form last Tuesday*, not *I have submitted the form last Tuesday*."}]' WHERE feedback_code = '01-01-01-005-01-00';
UPDATE feedback_items SET heading = 'Past habits and states (*used to* / *would*)', body = 'When to use: To talk about habits or situations in the past that are no longer true.
Key difference: *Used to* works for both repeated actions and past states (*be*, *have*, *live*, *like*). *Would* works only for repeated actions.
Look for: *when I was young*, *in my university days*, *in the past*.
Examples: Every summer, we *would study* (or *used to study*) together in the library. Professor Lee *used to live* in Cambridge (not *would live*).
Watch out: Do not use *would* for past states: *I used to have a car*, not *I would have a car*.', fields_json = '[{"label":"When to use","text":"To talk about habits or situations in the past that are no longer true."},{"label":"Key difference","text":"*Used to* works for both repeated actions and past states (*be*, *have*, *live*, *like*). *Would* works only for repeated actions."},{"label":"Look for","text":"*when I was young*, *in my university days*, *in the past*."},{"label":"Examples","text":"Every summer, we *would study* (or *used to study*) together in the library. Professor Lee *used to live* in Cambridge (not *would live*)."},{"label":"Watch out","text":"Do not use *would* for past states: *I used to have a car*, not *I would have a car*."}]' WHERE feedback_code = '01-01-01-005-02-00';
UPDATE feedback_items SET heading = 'Present Perfect (*has/have* + past participle)', body = 'When to use: For past actions that matter now, life experiences, and situations that started in the past and continue now.
Look for: *already*, *yet*, *ever*, *never*, *just*, *recently*, *so far*, *since 2020*, *for three years*.
Example: The department *has updated* the curriculum to meet new standards.
Watch out: Do not use it with a finished past time such as *yesterday* or *last week*: *I finished the report yesterday*, not *I have finished the report yesterday*.', fields_json = '[{"label":"When to use","text":"For past actions that matter now, life experiences, and situations that started in the past and continue now."},{"label":"Look for","text":"*already*, *yet*, *ever*, *never*, *just*, *recently*, *so far*, *since 2020*, *for three years*."},{"label":"Example","text":"The department *has updated* the curriculum to meet new standards."},{"label":"Watch out","text":"Do not use it with a finished past time such as *yesterday* or *last week*: *I finished the report yesterday*, not *I have finished the report yesterday*."}]' WHERE feedback_code = '01-01-01-005-03-00';
