UPDATE feedback_items SET heading = 'Time clauses (*when*, *while*, *as soon as*, *until*, *once*)', body = 'When to use: To say when something happens in relation to another action: before, after, at the same time or up to a point.
Key difference: *while* / *as* = at the same time; *as soon as* / *once* = immediately after; *until* = up to that point.
Example: We will leave *as soon as* the rain *stops*.
Watch out: Do not use *will* inside the time clause for the future: *as soon as the rain stops*, not *as soon as the rain will stop*.', fields_json = '[{"label":"When to use","text":"To say when something happens in relation to another action: before, after, at the same time or up to a point."},{"label":"Key difference","text":"*while* / *as* = at the same time; *as soon as* / *once* = immediately after; *until* = up to that point."},{"label":"Example","text":"We will leave *as soon as* the rain *stops*."},{"label":"Watch out","text":"Do not use *will* inside the time clause for the future: *as soon as the rain stops*, not *as soon as the rain will stop*."}]' WHERE feedback_code = '01-01-05-021-01-00';
