UPDATE feedback_items SET heading = '*even if* (a possible situation)', body = 'When to use: To say the result will not change, whatever happens.
Key difference: *even if* = a possible or imagined situation; *even though* = a real fact.
Example: *Even if* it rains tomorrow, the match will go ahead.
Watch out: Do not use *will* after *even if*: *Even if it rains*, not *Even if it will rain*.', fields_json = '[{"label":"When to use","text":"To say the result will not change, whatever happens."},{"label":"Key difference","text":"*even if* = a possible or imagined situation; *even though* = a real fact."},{"label":"Example","text":"*Even if* it rains tomorrow, the match will go ahead."},{"label":"Watch out","text":"Do not use *will* after *even if*: *Even if it rains*, not *Even if it will rain*."}]' WHERE feedback_code = '01-01-05-023-30-00';
UPDATE feedback_items SET heading = '*provided that*, *as long as*, *on condition that*', body = 'When to use: To set a condition that must be met for something to happen.
Look for: permission or an agreement that depends on something.
Example: You can borrow my car *as long as* you drive carefully.
Watch out: Do not use *will* after these words: *as long as you keep the receipt*, not *as long as you will keep the receipt*.', fields_json = '[{"label":"When to use","text":"To set a condition that must be met for something to happen."},{"label":"Look for","text":"permission or an agreement that depends on something."},{"label":"Example","text":"You can borrow my car *as long as* you drive carefully."},{"label":"Watch out","text":"Do not use *will* after these words: *as long as you keep the receipt*, not *as long as you will keep the receipt*."}]' WHERE feedback_code = '01-01-05-024-01-00';
UPDATE feedback_items SET heading = '*unless* (= if… not)', body = 'When to use: To say something will happen if a condition is not met.
Look for: *except if* meaning in the sentence.
Example: You cannot enter *unless* you have a ticket.
Watch out: *unless* already means *if not*, so do not add a negative: *unless you have a ticket*, not *unless you don''t have a ticket*.', fields_json = '[{"label":"When to use","text":"To say something will happen if a condition is not met."},{"label":"Look for","text":"*except if* meaning in the sentence."},{"label":"Example","text":"You cannot enter *unless* you have a ticket."},{"label":"Watch out","text":"*unless* already means *if not*, so do not add a negative: *unless you have a ticket*, not *unless you don''t have a ticket*."}]' WHERE feedback_code = '01-01-05-024-02-00';
UPDATE feedback_items SET heading = '*in case* (to be prepared)', body = 'When to use: To say you do something as a precaution, because something might happen.
Key difference: *in case* = do it now to be ready; *if* = do it only when the event happens.
Example: Take an umbrella *in case* it rains.
Watch out: Do not use *will* after *in case*: *in case it rains*, not *in case it will rain*.', fields_json = '[{"label":"When to use","text":"To say you do something as a precaution, because something might happen."},{"label":"Key difference","text":"*in case* = do it now to be ready; *if* = do it only when the event happens."},{"label":"Example","text":"Take an umbrella *in case* it rains."},{"label":"Watch out","text":"Do not use *will* after *in case*: *in case it rains*, not *in case it will rain*."}]' WHERE feedback_code = '01-01-05-024-03-00';
