UPDATE feedback_items SET heading = 'First conditional with *can* / *may* / *might*', body = 'When to use: When the result is a possibility or permission rather than a certainty.
Key difference: *will* = sure result; *may* / *might* = possible result; *can* = permission or ability.
Example: *If* she *passes* the interview, she *might get* the job.
Watch out: Do not put the modal in the *if*-part: *If you finish, you can leave*, not *If you can finish, you can leave*.', fields_json = '[{"label":"When to use","text":"When the result is a possibility or permission rather than a certainty."},{"label":"Key difference","text":"*will* = sure result; *may* / *might* = possible result; *can* = permission or ability."},{"label":"Example","text":"*If* she *passes* the interview, she *might get* the job."},{"label":"Watch out","text":"Do not put the modal in the *if*-part: *If you finish, you can leave*, not *If you can finish, you can leave*."}]' WHERE feedback_code = '01-01-06-026-12-00';
