UPDATE feedback_items SET heading = 'Second conditional: imagined present or future', body = 'When to use: For situations that are unreal, unlikely or imagined now or in the future.
Look for: *if* + past simple, then *would* + base verb.
Example: *If* I *won* the lottery, I *would travel* the world.
Watch out: Do not use *would* in the *if*-part: *If I won*, not *If I would win*.', fields_json = '[{"label":"When to use","text":"For situations that are unreal, unlikely or imagined now or in the future."},{"label":"Look for","text":"*if* + past simple, then *would* + base verb."},{"label":"Example","text":"*If* I *won* the lottery, I *would travel* the world."},{"label":"Watch out","text":"Do not use *would* in the *if*-part: *If I won*, not *If I would win*."}]' WHERE feedback_code = '01-01-06-027-01-00';
UPDATE feedback_items SET heading = 'Second conditional: imagined present or future', body = 'When to use: For situations that are unreal, unlikely or imagined now or in the future.
Look for: *if* + past simple, then *would* + base verb.
Example: *If* I *won* the lottery, I *would travel* the world.
Watch out: Do not use *would* in the *if*-part: *If I won*, not *If I would win*.', fields_json = '[{"label":"When to use","text":"For situations that are unreal, unlikely or imagined now or in the future."},{"label":"Look for","text":"*if* + past simple, then *would* + base verb."},{"label":"Example","text":"*If* I *won* the lottery, I *would travel* the world."},{"label":"Watch out","text":"Do not use *would* in the *if*-part: *If I won*, not *If I would win*."}]' WHERE feedback_code = '01-01-06-027-02-00';
UPDATE feedback_items SET heading = '*If I were you…* (*were* for imagined situations)', body = 'When to use: To give advice or describe an imagined situation with *be*.
Look for: *if* + subject + *were* / *weren''t* in a second conditional.
Example: *If I were you*, I would apologise.
Watch out: *If I was you* is common in speech, but *were* is the formal and expected answer.', fields_json = '[{"label":"When to use","text":"To give advice or describe an imagined situation with *be*."},{"label":"Look for","text":"*if* + subject + *were* / *weren''t* in a second conditional."},{"label":"Example","text":"*If I were you*, I would apologise."},{"label":"Watch out","text":"*If I was you* is common in speech, but *were* is the formal and expected answer."}]' WHERE feedback_code = '01-01-06-027-03-00';
UPDATE feedback_items SET heading = 'Second conditional with *could* / *might*', body = 'When to use: When the imagined result is an ability (*could*) or a possibility (*might*).
Look for: *if* + past simple, then *could* / *might* + base verb.
Example: *If* we *had* a garden, we *could grow* our own vegetables.
Watch out: Keep both parts ‘past’: *If he knew the answer, he could tell us*, not *If he knew the answer, he can tell us*.', fields_json = '[{"label":"When to use","text":"When the imagined result is an ability (*could*) or a possibility (*might*)."},{"label":"Look for","text":"*if* + past simple, then *could* / *might* + base verb."},{"label":"Example","text":"*If* we *had* a garden, we *could grow* our own vegetables."},{"label":"Watch out","text":"Keep both parts ‘past’: *If he knew the answer, he could tell us*, not *If he knew the answer, he can tell us*."}]' WHERE feedback_code = '01-01-06-027-04-00';
