UPDATE feedback_items SET heading = 'Third conditional with *might have*', body = 'When to use: To talk about a past result that was possible but not certain.
Key difference: *would have* = certain result; *might have* = possible result.
Example: *If* we *had left* earlier, we *might have found* a parking space.
Watch out: Use *might have* + past participle, not *might* + base verb, for the past.', fields_json = '[{"label":"When to use","text":"To talk about a past result that was possible but not certain."},{"label":"Key difference","text":"*would have* = certain result; *might have* = possible result."},{"label":"Example","text":"*If* we *had left* earlier, we *might have found* a parking space."},{"label":"Watch out","text":"Use *might have* + past participle, not *might* + base verb, for the past."}]' WHERE feedback_code = '01-01-06-028-26-00';
