UPDATE feedback_items SET heading = 'No tense change after a present reporting verb', body = 'When to use: When the reporting verb is in the present (*says*, *tells*, *explains*), often for news or messages just received.
Look for: *says* / *tells* + reported words. Keep the original tense.
Example: She *says* she *wants* to leave early.
Watch out: Do not move the tense back after a present verb: *She says she wants*, not *She says she wanted*.', fields_json = '[{"label":"When to use","text":"When the reporting verb is in the present (*says*, *tells*, *explains*), often for news or messages just received."},{"label":"Look for","text":"*says* / *tells* + reported words. Keep the original tense."},{"label":"Example","text":"She *says* she *wants* to leave early."},{"label":"Watch out","text":"Do not move the tense back after a present verb: *She says she wants*, not *She says she wanted*."}]' WHERE feedback_code = '01-01-07-031-30-00';
UPDATE feedback_items SET heading = 'Reported *wh*- questions (word order)', body = 'When to use: When reporting a question with *what*, *where*, *when*, *why*, *how* or *who*.
Look for: question word + subject + verb (tense moved back).
Example: ‘Where are you going?’ → She asked *where I was going*.
Watch out: Do not use question order: *where I was going*, not *where was I going* or *where did I go*.', fields_json = '[{"label":"When to use","text":"When reporting a question with *what*, *where*, *when*, *why*, *how* or *who*."},{"label":"Look for","text":"question word + subject + verb (tense moved back)."},{"label":"Example","text":"‘Where are you going?’ → She asked *where I was going*."},{"label":"Watch out","text":"Do not use question order: *where I was going*, not *where was I going* or *where did I go*."}]' WHERE feedback_code = '01-01-07-032-01-00';
UPDATE feedback_items SET heading = 'Reported yes/no questions (*asked if* / *whether*)', body = 'When to use: When reporting a question that has a yes/no answer.
Look for: *asked* / *wanted to know* + *if* / *whether* + subject + verb (with the tense moved back).
Example: ‘Have you seen the email?’ → He asked *if I had seen* the email.
Watch out: Use statement order, with no *do* / *did*: *asked if I had seen*, not *asked if had I seen* or *asked if did I see*.', fields_json = '[{"label":"When to use","text":"When reporting a question that has a yes/no answer."},{"label":"Look for","text":"*asked* / *wanted to know* + *if* / *whether* + subject + verb (with the tense moved back)."},{"label":"Example","text":"‘Have you seen the email?’ → He asked *if I had seen* the email."},{"label":"Watch out","text":"Use statement order, with no *do* / *did*: *asked if I had seen*, not *asked if had I seen* or *asked if did I see*."}]' WHERE feedback_code = '01-01-07-032-02-00';
