UPDATE feedback_items SET heading = '*It is* + adjective + *for* + person + *to*', body = 'When to use: To say how important, usual or difficult an action is for someone.
Look for: *crucial*, *essential*, *unusual*, *important* + *for* + person + *to*.
Example: It is *unusual for him to miss* a meeting.
Watch out: Use *for* and an object pronoun: *for him*, not *of him* or *for he*.', fields_json = '[{"label":"When to use","text":"To say how important, usual or difficult an action is for someone."},{"label":"Look for","text":"*crucial*, *essential*, *unusual*, *important* + *for* + person + *to*."},{"label":"Example","text":"It is *unusual for him to miss* a meeting."},{"label":"Watch out","text":"Use *for* and an object pronoun: *for him*, not *of him* or *for he*."}]' WHERE feedback_code = '01-01-08-038-19-00';
UPDATE feedback_items SET heading = 'Possessive + *-ing* (*your taking*, *our being*)', body = 'When to use: In formal English, when a person does the *-ing* action.
Look for: *appreciate*, *unaware of* and similar words followed by a person + *-ing*.
Example: We *appreciate your taking* the time to reply.
Watch out: *appreciate you taking* is common in everyday English, but the possessive (*your*) is preferred in formal writing.', fields_json = '[{"label":"When to use","text":"In formal English, when a person does the *-ing* action."},{"label":"Look for","text":"*appreciate*, *unaware of* and similar words followed by a person + *-ing*."},{"label":"Example","text":"We *appreciate your taking* the time to reply."},{"label":"Watch out","text":"*appreciate you taking* is common in everyday English, but the possessive (*your*) is preferred in formal writing."}]' WHERE feedback_code = '01-01-08-038-20-00';
UPDATE feedback_items SET heading = '*Having* + past participle (*Having gathered…*)', body = 'When to use: To show that one action was completed before the next.
Look for: two actions done by the same person or group, one after the other.
Example: *Having gathered* the data, the team analysed it.
Watch out: The subject after the comma must be the one who did the first action: *Having gathered the data, the team analysed it*, not *Having gathered the data, it was analysed*.', fields_json = '[{"label":"When to use","text":"To show that one action was completed before the next."},{"label":"Look for","text":"two actions done by the same person or group, one after the other."},{"label":"Example","text":"*Having gathered* the data, the team analysed it."},{"label":"Watch out","text":"The subject after the comma must be the one who did the first action: *Having gathered the data, the team analysed it*, not *Having gathered the data, it was analysed*."}]' WHERE feedback_code = '01-01-08-038-21-00';
UPDATE feedback_items SET heading = 'Passive *-ing* and *to* forms (*being seen*, *to be told*)', body = 'When to use: When the subject receives the action rather than doing it.
Look for: *avoid* / *dislike* + *being* + past participle; *demand* / *expect* + *to be* + past participle.
Example: He wore sunglasses to *avoid being seen*.
Watch out: *avoid seeing* means you do not look; *avoid being seen* means others do not see you.', fields_json = '[{"label":"When to use","text":"When the subject receives the action rather than doing it."},{"label":"Look for","text":"*avoid* / *dislike* + *being* + past participle; *demand* / *expect* + *to be* + past participle."},{"label":"Example","text":"He wore sunglasses to *avoid being seen*."},{"label":"Watch out","text":"*avoid seeing* means you do not look; *avoid being seen* means others do not see you."}]' WHERE feedback_code = '01-01-08-038-22-00';
UPDATE feedback_items SET heading = 'Perfect and negative *-ing* forms (*having done*, *not having done*)', body = 'When to use: To show an action was completed earlier, often after *regret*, *after* or *report*.
Look for: a past action or regret; put *not* before *having* or the *-ing* word.
Example: He *regretted not having followed* the instructions.
Watch out: *not* usually goes first (*not having followed*), and the verb must keep its *-ing* form: not *regretted not follow*.', fields_json = '[{"label":"When to use","text":"To show an action was completed earlier, often after *regret*, *after* or *report*."},{"label":"Look for","text":"a past action or regret; put *not* before *having* or the *-ing* word."},{"label":"Example","text":"He *regretted not having followed* the instructions."},{"label":"Watch out","text":"*not* usually goes first (*not having followed*), and the verb must keep its *-ing* form: not *regretted not follow*."}]' WHERE feedback_code = '01-01-08-038-23-00';
