UPDATE feedback_items SET heading = 'Adjective + *for* + person + *to* (*essential for him to…*)', body = 'When to use: To say how important, usual or easy an action is for someone.
Look for: *essential*, *crucial*, *unusual*, *common*, *important* + *for* + person + (*to be*) *to*.
Example: It is *crucial for the documents to be reviewed* by a lawyer.
Watch out: Use an object pronoun after *for*: *for him*, not *for he*; and not *of him*.', fields_json = '[{"label":"When to use","text":"To say how important, usual or easy an action is for someone."},{"label":"Look for","text":"*essential*, *crucial*, *unusual*, *common*, *important* + *for* + person + (*to be*) *to*."},{"label":"Example","text":"It is *crucial for the documents to be reviewed* by a lawyer."},{"label":"Watch out","text":"Use an object pronoun after *for*: *for him*, not *for he*; and not *of him*."}]' WHERE feedback_code = '01-01-08-039-04-00';
UPDATE feedback_items SET heading = 'Possessive + *-ing* (formal)', body = 'When to use: In formal English, when a person does the *-ing* action.
Look for: *appreciate*, *unaware of*, *by* + a person + *-ing*.
Example: We were *unaware of his having been* promoted.
Watch out: *you taking* and *them leaving* are common in speech, but *your taking* and *their leaving* are preferred in formal writing.', fields_json = '[{"label":"When to use","text":"In formal English, when a person does the *-ing* action."},{"label":"Look for","text":"*appreciate*, *unaware of*, *by* + a person + *-ing*."},{"label":"Example","text":"We were *unaware of his having been* promoted."},{"label":"Watch out","text":"*you taking* and *them leaving* are common in speech, but *your taking* and *their leaving* are preferred in formal writing."}]' WHERE feedback_code = '01-01-08-039-05-00';
UPDATE feedback_items SET heading = '*Having* + past participle (participle clauses)', body = 'When to use: To show the first action finished before the second, done by the same subject.
Look for: two actions in sequence.
Example: *Having gathered* all the evidence, the investigators wrote their report.
Watch out: Use *Having gathered*, not *Gathering*, when the first action was completed first.', fields_json = '[{"label":"When to use","text":"To show the first action finished before the second, done by the same subject."},{"label":"Look for","text":"two actions in sequence."},{"label":"Example","text":"*Having gathered* all the evidence, the investigators wrote their report."},{"label":"Watch out","text":"Use *Having gathered*, not *Gathering*, when the first action was completed first."}]' WHERE feedback_code = '01-01-08-039-06-00';
UPDATE feedback_items SET heading = 'Passive *to be done* / *being done*', body = 'When to use: When the subject receives the action.
Key difference: *demand* / *expect* / *honoured* + *to be* + past participle; *avoid* / *dislike* / *regret* + *being* + past participle.
Example: The committee *demanded to be informed* of any changes.
Watch out: Check who does the action: *avoid being seen* (others see you), not *avoid seeing*.', fields_json = '[{"label":"When to use","text":"When the subject receives the action."},{"label":"Key difference","text":"*demand* / *expect* / *honoured* + *to be* + past participle; *avoid* / *dislike* / *regret* + *being* + past participle."},{"label":"Example","text":"The committee *demanded to be informed* of any changes."},{"label":"Watch out","text":"Check who does the action: *avoid being seen* (others see you), not *avoid seeing*."}]' WHERE feedback_code = '01-01-08-039-07-00';
UPDATE feedback_items SET heading = '*having done* / *having been done*', body = 'When to use: To show that an action was completed earlier, after a verb or preposition.
Look for: *deny*, *despite*, *for* + an earlier action.
Example: *Despite having been warned* twice, he made the same mistake.
Watch out: Use *having* + past participle for the earlier action, with *not* usually placed first: *for not having replied*.', fields_json = '[{"label":"When to use","text":"To show that an action was completed earlier, after a verb or preposition."},{"label":"Look for","text":"*deny*, *despite*, *for* + an earlier action."},{"label":"Example","text":"*Despite having been warned* twice, he made the same mistake."},{"label":"Watch out","text":"Use *having* + past participle for the earlier action, with *not* usually placed first: *for not having replied*."}]' WHERE feedback_code = '01-01-08-039-08-00';
