UPDATE feedback_items SET heading = 'Starting with an *-ing* phrase (*Walking home, she…*)', body = 'When to use: To describe an action, feeling or reason connected with the subject of the main sentence.
Look for: an *-ing* phrase at the start, followed by a comma and the person who does that action.
Example: *Walking* down the trail, *she* admired the autumn leaves.
Watch out: The subject after the comma must be the one doing the action: *Walking home, I saw a fox*, not *Walking home, a fox was seen*.', fields_json = '[{"label":"When to use","text":"To describe an action, feeling or reason connected with the subject of the main sentence."},{"label":"Look for","text":"an *-ing* phrase at the start, followed by a comma and the person who does that action."},{"label":"Example","text":"*Walking* down the trail, *she* admired the autumn leaves."},{"label":"Watch out","text":"The subject after the comma must be the one doing the action: *Walking home, I saw a fox*, not *Walking home, a fox was seen*."}]' WHERE feedback_code = '01-01-11-051-01-00';
UPDATE feedback_items SET heading = 'Noun + *-ing* (*the man playing the violin*)', body = 'When to use: To describe a person or thing by what it is doing (short for *who* / *which is doing*).
Look for: a noun followed by an action that describes it.
Example: We listened to the street musician *playing* the violin.
Watch out: Do not use a past verb or *was* + *-ing* without *who*: *the musician playing*, not *the musician played* or *the musician was playing*.', fields_json = '[{"label":"When to use","text":"To describe a person or thing by what it is doing (short for *who* / *which is doing*)."},{"label":"Look for","text":"a noun followed by an action that describes it."},{"label":"Example","text":"We listened to the street musician *playing* the violin."},{"label":"Watch out","text":"Do not use a past verb or *was* + *-ing* without *who*: *the musician playing*, not *the musician played* or *the musician was playing*."}]' WHERE feedback_code = '01-01-11-051-02-00';
