UPDATE feedback_items SET heading = '*Having* + past participle (*Having finished…*)', body = 'When to use: To show that the subject completed one action before the next.
Look for: two actions in order, done by the same person.
Example: *Having completed* the draft, the author sent it to the publisher.
Watch out: Use *Having* + past participle, not *Had* + past participle: *Having completed the report, she left*, not *Had completed the report, she left*.', fields_json = '[{"label":"When to use","text":"To show that the subject completed one action before the next."},{"label":"Look for","text":"two actions in order, done by the same person."},{"label":"Example","text":"*Having completed* the draft, the author sent it to the publisher."},{"label":"Watch out","text":"Use *Having* + past participle, not *Had* + past participle: *Having completed the report, she left*, not *Had completed the report, she left*."}]' WHERE feedback_code = '01-01-11-053-01-00';
UPDATE feedback_items SET heading = '*Having been* + past participle (*Having been warned…*)', body = 'When to use: To show that something was done to the subject before the next action.
Look for: a passive idea first (*was warned*, *was told*, *was chosen*), then the main action.
Example: *Having been warned* about the storm, the campers moved to higher ground.
Watch out: Keep *been* when the subject received the action: *Having been told*, not *Having told* (which means they told someone else).', fields_json = '[{"label":"When to use","text":"To show that something was done to the subject before the next action."},{"label":"Look for","text":"a passive idea first (*was warned*, *was told*, *was chosen*), then the main action."},{"label":"Example","text":"*Having been warned* about the storm, the campers moved to higher ground."},{"label":"Watch out","text":"Keep *been* when the subject received the action: *Having been told*, not *Having told* (which means they told someone else)."}]' WHERE feedback_code = '01-01-11-053-02-00';
